      "content": "#!/usr/bin/env bash\nset -euo pipefail\n\nLOG_FILE=\"$1\"\n\n# Filter ERROR lines, extract message, remove variable key=value pairs, count occurrences\ngrep \" ERROR \" \"$LOG_FILE\" | \\\n    sed 's/^[^ ]* ERROR //' | \\\n    sed 's/ [a-zA-Z_]*=[^ ]*//g' | \\\n    sort | uniq -c | sort -rn | \\\n    awk '{count=$1; $1=\"\"; sub(/^ /, \"\"); print count \" \" $0}'\n"
